  "微软登录失败（HTTP {code}）": { en: "Microsoft sign-in failed (HTTP {code})", ja: "Microsoft へのログインに失敗しました（HTTP {code}）", "zh-Hant": "微軟登入失敗（HTTP {code}）" },
  "微软登录失败：{msg}": { en: "Microsoft sign-in failed: {msg}", ja: "Microsoft へのログインに失敗しました：{msg}", "zh-Hant": "微軟登入失敗：{msg}" },
  "忘了密码时，只能用这个恢复密钥打开加密的照片。请抄在纸上或存进密码管理器，Zyll 不会再显示它。": { en: "If you forget your password, this recovery key is the only way to open your encrypted photos. Write it down or store it in a password manager; Zyll won't show it again.", ja: "パスワードを忘れたとき、暗号化された写真を開けるのはこの回復キーだけです。紙に書くかパスワードマネージャーに保存してください。Zyll では二度と表示されません。", "zh-Hant": "忘了密碼時，只能用這個恢復金鑰開啟加密的照片。請抄在紙上或存進密碼管理器，Zyll 不會再顯示它。" },
  "我已经保存好了": { en: "I have saved it", ja: "保存しました", "zh-Hant": "我已經儲存好了" },
